        HolidayEpisode(seriesTmdbId = 1100, seriesImdbId = "tt0460649", seriesName = "How I Met Your Mother", season = 8, episode = 12, episodeTmdbId = 62935, title = "The Final Page (2)", airDate = "2012-12-17", still = "/pob1qldd3exV5ZYqNCKsqMZclAs.jpg", seasonPoster = "/o6BepKycT39kubElBsnj5bWpDPU.jpg", seriesBackdrop = "/3f8aW6vcYRP6mTZdgXm83BiuB9t.jpg", seriesPoster = "/b34jPzmB0wZy7EjUZoleXOl2RRI.jpg", runtime = 23, overview = "Christmas approaches and Ted wrestles with whether to tell Robin about Barney's intentions involving Patrice, while Marshall and Lily get an early Yule gift, a night away from Marvin, but a case of separation anxiety strikes and threatens to ruin the evening."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 1, episode = 9, episodeTmdbId = 153595, title = "Mr. Hankey, the Christmas Poo", airDate = "1997-12-17", still = "/kJUySO9RugdeRt7TKUxwkAMzO5z.jpg", seasonPoster = "/sxCj0Iun46sUUsF5I2NQY6rml4c.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "South Park Elementary is on stage rehearsing for the schools play. Kyle begins to sing a song about Mr. Hankey, the Christmas Poo. Of course, no one has any idea what the heck he's singing about. Kyle explains that Mr. Hankey comes every year to all the good boys and girls who have a lot of fiber in their diet. Everyone thinks he's insane and he gets sent to a mental institute."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 2, episode = 16, episodeTmdbId = 153615, title = "Merry Christmas Charlie Manson!", airDate = "1998-12-09", still = "/AdCwM8y7EIx1QHdBzFUsCpEdj0p.jpg", seasonPoster = "/fSlMHxDB6Ln9V1wwuI9M1ylcE68.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "Kyle, Stan and Kenny accompany Eric and his family to a Christmas celebration with the Cartman family. One of Cartman's relatives breaks out of jail for the reunion, with his cellmate, Charles Manson."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 3, episode = 15, episodeTmdbId = 153632, title = "Mr. Hankey's Christmas Classics", airDate = "1999-12-01", still = "/9Cna6t5Amu0j48ibL3R04KZSdyR.jpg", seasonPoster = "/996EYWRu4zksbNodgs1Omri02Yi.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "Mr. Hankey introduces 10 musical segments highlighting songs the on the CD \"Mr. Hankey's Christmas Classics.\" The boys and all of the other South Park characters sing their own songs for the Holidays and realize that Christmas is all about the presents."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 4, episode = 17, episodeTmdbId = 153651, title = "A Very Crappy Christmas", airDate = "2000-12-20", still = "/31KGmoygf7vTxSVy7ClVwfde2OK.jpg", seasonPoster = "/kqJ3yofZa2bVQNC3wl0CQV5EUmr.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "Kyle and Ike anxiously await Mr. Hankey. When he doesn't show, Kyle calls the others for a late night emergency meeting. They find Mr. Hankey living with his alcoholic wife and their three little nuggets. He tells them that no one is into Christmas. They all decide to try and spread some Christmas cheer. Their effort fails and the boys decide to create an animated special of their own. Featuring J"),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 6, episode = 17, episodeTmdbId = 153682, title = "Red Sleigh Down", airDate = "2002-12-11", still = "/JCTvi44c2hWzabvrxh7H4sAc9u.jpg", seasonPoster = "/7nKjCuBH0tGkLwBwxDgxbBrNj5F.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "In an effort to redeem himself days before Christmas, Cartman decides to bring Christmas to the Iraqis. So, along with Stan, Kyle, and Kenny they catch a ride with Mr. Hankey to the North Pole to bring Christmas to Iraq."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 7, episode = 15, episodeTmdbId = 153697, title = "It's Christmas in Canada", airDate = "2003-12-17", still = "/rvYPyF159ZTmkWf7robogO7Mhu0.jpg", seasonPoster = "/zYHoEtNxkdAa4g8wPdBdGq8VOzC.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "When Ike is claimed by his Canadian birth parents, the boys set out to gain an audience with the Canadian Prime Minister. Meanwhile, Cartman's biggest concern is that the boys don't spend all of Christmas in Canada."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 8, episode = 14, episodeTmdbId = 153711, title = "Woodland Critter Christmas", airDate = "2004-12-15", still = "/krHPN6i1uIDmSl5ZyfbMQAiECgt.jpg", seasonPoster = "/aTTmEQqmlVGNHNKJ8K4rFAnZrPo.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "Stan is approached by the forest critters and asked to help them build a manger in anticipation of the birth of their Lord and Savior. Stan complies, only to find out that they serve a very different Lord."),
        HolidayEpisode(seriesTmdbId = 2190, seriesImdbId = "tt0121955", seriesName = "South Park", season = 23, episode = 10, episodeTmdbId = 1991489, title = "Christmas Snow", airDate = "2019-12-11", still = "/1xg5YEgrkKNrNLZL6GfGmm4qfAu.jpg", seasonPoster = "/to2dtGxOcgpbkjZNSXizDZbrihn.jpg", seriesBackdrop = "/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg", seriesPoster = "/k7n2EVge7G77eMr3brztRGG1fFU.jpg", runtime = 23, overview = "Santa is stealing all the joy from the town's Holiday Season."),
