        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 10, episode = 4, episodeTmdbId = 62447, title = "Treehouse of Horror IX", airDate = "1998-10-25", still = "/dwicl3ahKPqKdyXvvpJav3fgPb7.jpg", seasonPoster = "/A77xKuxA13aXA1mQd6YLAaTIErK.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "In \"Hell Toupée,\" Snake is sent to the electric chair, and his hair is transplanted onto Homer. In \"The Terror of Tiny Toon,\" Bart and Lisa become cartoon characters in an episode of Itchy & Scratchy. In \"Starship Poopers,\" a growth spurt casts doubt on Maggie's paternity, and the family goes on the Jerry Springer show."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 11, episode = 4, episodeTmdbId = 62453, title = "Treehouse of Horror X", airDate = "1999-10-31", still = "/k4azXLZCuz4SqfqHO5yZ5S0MAS.jpg", seasonPoster = "/7lgnlOENoCdub15UijLKTHawyhm.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "In \"I Know What You Diddily-Iddly-Did\" the Simpsons fear they have killed Ned Flanders. \"Desperately Xeeking Xena\" satirizes superheroes of yore with \"Stretch Dude\" Bart and \"Clobber Girl\" Lisa. And \"Life's A Glitch, Then You Die\" depicts the upcoming horror of Y2K."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 12, episode = 1, episodeTmdbId = 62474, title = "Treehouse of Horror XI", airDate = "2000-11-01", still = "/w5WbT0dzggTabsPM9fTqzxvJIQA.jpg", seasonPoster = "/jfxiyjRLoQq9LavlFNRBgjuweg5.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "This year's Halloween story sees The Simpsons as \"The Munsters\" (with everyone except Lisa getting killed), Homer as a wandering spirit on the hunt for a good deed in \"G-G-Ghost D-D-Dad,\" Bart and Lisa as peasants in a fairy tale forest in \"Scary Tales Can Come True,\" and Lisa inadvertently dooming mankind by rescuing a dolphin in \"Night of the Dolphin.\""),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 13, episode = 1, episodeTmdbId = 62498, title = "Treehouse of Horror XII", airDate = "2001-11-06", still = "/9RELyTRHODqvYEWPjaZ35YO3zVp.jpg", seasonPoster = "/xflc3aV1SbP2bGeZNuu4AG6cIqH.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "In the twelfth Treehouse of Horror episode:\n\nHex and the City – While on a day trip through Ethnictown, Homer's bumbling catches the ire of a gypsy, who curses Homer's family and friends into receiving nothing but bad luck.\n\nHouse of Whacks – in this mixed parody of Demon Seed and 2001: A Space Odyssey, Marge buys an automated house and customizes it with the Pierce Brosnan personality, who falls "),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 14, episode = 1, episodeTmdbId = 62517, title = "Treehouse of Horror XIII", airDate = "2002-11-03", still = "/shHP5cjpOrQkz5FZfzwkrxmjGDo.jpg", seasonPoster = "/9IowK57TpeO09D4B46jd4J3wjPO.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "The 13th Treehouse of Horror episode, consisting of three self-contained segments.\n\nSend in the Clones – Homer buys a hammock that can produce clones of himself. He creates numerous clones to help him around the house, but they soon overrun Springfield.\n\nThe Fright to Creep and Scare Harms – Lisa petitions the town to get rid of their firearms after discovering the gravestone of a young man named "),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 15, episode = 1, episodeTmdbId = 62558, title = "Treehouse of Horror XIV", airDate = "2003-11-02", still = "/4XAfPywguzhK2voqI9Nu6K5hIRH.jpg", seasonPoster = "/bmMwmEfwmziKzWP2jiU0GMw8yKd.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "\"Reaper Madness\" - Death becomes Homer and our hero must learn to reap what he sows (and pull a fast one on the almighty). \"Frinkenstein\" - Soon to be Nobel-prize winning Professor Frink reanimates his father for some gruesome body parts-swapping. \"Stop the World, I Want to Goof Off\" - A parody of Clockstoppers, starring Bart and Milhouse."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 16, episode = 1, episodeTmdbId = 62574, title = "Treehouse of Horror XV", airDate = "2004-11-07", still = "/cIegZWMyMbDf4fcbROoAdSkmcT8.jpg", seasonPoster = "/ifjiG1gHGRyYmNDWRb9Ul9VCfEn.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "Ned Flanders' head injury gives him the power to predict others' deaths, Bart and Lisa play detective when a string of Victorian-era prostitutes are murdered by Jack the Ripper, and the Simpsons go on a fantastic voyage inside Mr. Burns' body to save Maggie."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 17, episode = 4, episodeTmdbId = 62582, title = "Treehouse of Horror XVI", airDate = "2005-11-06", still = "/yAtfVc7UEoKxw7xupCkNP5rSlOJ.jpg", seasonPoster = "/evIWfK3hKFIExETjv6L2YS9J8fw.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "Bart ends up in a coma after attempting to jump from the roof to the swimming pool at Spinster Arms Apartments, while attending a hunting party at Burns Manor, Homer panics and believes the prey is the hunting party, and after losing a Halloween costume contest to Dr Hibbert as Dracula, a real witch puts a spell on the people of Springfield."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 18, episode = 4, episodeTmdbId = 62616, title = "Treehouse of Horror XVII", airDate = "2006-11-05", still = "/yRWtv3xDq395srLCrAS5ChBc9Zp.jpg", seasonPoster = "/kwb8AZAHyhn96dzn17mtTV3l8dl.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "The 17th annual Halloween trilogy. Included: \"Married to the Blob,\" in which a meteor turns Homer into a monster; \"You Gotta Know When to Golem,\" about a monster from Jewish folklore; and \"The Day the Earth Looked Stupid,\" about an alien invasion."),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 19, episode = 5, episodeTmdbId = 62626, title = "Treehouse of Horror XVIII", airDate = "2007-11-04", still = "/yjmaAEE5wBMbAfPCOHbI2YRLmqF.jpg", seasonPoster = "/nLKZJ1ozVvYFtaOynzkShE8wN4k.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "The series' 18th Halloween show features three vignettes that parody movies: one that spoofs \"Mr. & Mrs. Smith\"; one that sends up \"E.T.\"; and one that parodies \"Se7en.\""),
        HolidayEpisode(seriesTmdbId = 456, seriesImdbId = "tt0096697", seriesName = "The Simpsons", season = 20, episode = 4, episodeTmdbId = 62646, title = "Treehouse of Horror XIX", airDate = "2008-11-02", still = "/tDOgPUJ3qxgHBI63R6d1cGwHixE.jpg", seasonPoster = "/2CUdLX4K8fMlcdVPHUbciTYt4ri.jpg", seriesBackdrop = "/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg", seriesPoster = "/tf0CUEynk6GfmrlHIQKQ5mfFP5P.jpg", runtime = 23, overview = "Springfield is the setting for parodies of Charlie Brown, It's the Great Pumpkin and Michael Bay's Transformers as Homer's vote on election day is misread by a renegade machine."),
